<?php
namespace Database\Seeders;use App\Models\{Account,FinancialAccount,HotelBusinessDate,Property};use Illuminate\Database\Seeder;
class HotelAccountingSeeder extends Seeder{public function run():void{foreach(Property::all() as $p){$rows=[['1000','Cash on Hand','asset','cash'],['1010','Bank Account','asset','bank'],['1020','MTN MoMo','asset','mobile_money'],['1030','Airtel Money','asset','mobile_money'],['1100','Accounts Receivable','asset','receivable'],['1200','Inventory','asset','inventory'],['1300','Input VAT / Tax Receivable','asset','tax'],['1500','Fixed Assets','asset','fixed_asset'],['2000','Accounts Payable','liability','payable'],['2100','Output VAT / Tax Payable','liability','tax'],['2200','Guest Deposits','liability','other'],['3000','Owner Capital','equity','capital'],['3100','Retained Earnings','equity','retained_earnings'],['4100','Room Revenue','income','room_revenue'],['4200','Restaurant Revenue','income','restaurant_revenue'],['4300','Bar Revenue','income','bar_revenue'],['4400','Other Hotel Revenue','income','other_revenue'],['5100','Cost of Sales / Purchases','expense','cost_of_sales'],['5200','Payroll Expense','expense','operating_expense'],['5300','Utilities Expense','expense','operating_expense'],['5400','Repairs & Maintenance','expense','operating_expense'],['5500','Administrative Expense','expense','operating_expense']];foreach($rows as[$code,$name,$type,$sub])Account::firstOrCreate(['property_id'=>$p->id,'code'=>$code],['name'=>$name,'type'=>$type,'subtype'=>$sub,'is_control'=>in_array($code,['1100','1200','2000'],true),'is_active'=>true]);foreach([['cash','Main Cash','1000',null],['bank','Main Bank','1010',null],['mobile_money','MTN MoMo','1020','MTN'],['mobile_money','Airtel Money','1030','Airtel']] as[$type,$name,$code,$provider])FinancialAccount::firstOrCreate(['property_id'=>$p->id,'name'=>$name],['account_id'=>Account::where('property_id',$p->id)->where('code',$code)->value('id'),'type'=>$type,'provider'=>$provider,'currency'=>config('hms.currency','UGX'),'active'=>true]);HotelBusinessDate::firstOrCreate(['property_id'=>$p->id,'business_date'=>now()->toDateString()],['status'=>'open','opened_at'=>now()]);}}}
